// Verus solution: rotate a non-empty list left by n (0 < n < len)
//
// Result == list[n..] ++ list[..n]
use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list.len() == list.len(),
        // Elements from n..len move to the front
        forall|i: usize|
            i < list.len() - n ==> new_list[i] == list[n + i],
        // Elements from 0..n move to the back (preserving order)
        forall|i: usize|
            i < n ==> new_list[(list.len() - n) + i] == list[i],
{
    let len = list.len();
    let mut out: Vec<i32> = Vec::new();

    // Append list[n..len]
    let mut i: usize = n;
    while i < len
        invariant
            len == list.len(),
            0 < n,
            n < len,
            n <= i <= len,
            out.len() == i - n,
            forall|k: usize| k < out.len() ==> out[k] == list[n + k],
        decreases len - i
    {
        out.push(list[i]);
        i += 1;
    }

    // Append list[0..n]
    let mut j: usize = 0;
    while j < n
        invariant
            len == list.len(),
            0 < n,
            n < len,
            0 <= j <= n,
            out.len() == (len - n) + j,
            // First chunk (list[n..len]) is intact
            forall|k: usize|
                k < len - n ==> out[k] == list[n + k],
            // Second chunk so far matches list[0..j]
            forall|k: usize|
                k < j ==> out[(len - n) + k] == list[k],
        decreases n - j
    {
        out.push(list[j]);
        j += 1;
    }

    // Optional sanity asserts (helpful if you extend the proof later)
    assert(out.len() == len);

    out
}

} // verus!